package com.hallbooking.servlet;import com.hallbooking.dao.BookingDAO;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.Date;
@WebServlet("/book") public class BookingServlet extends HttpServlet{protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{try{int uid=Integer.parseInt(q.getParameter("userId"));int hid=Integer.parseInt(q.getParameter("hallId"));Date d=Date.valueOf(q.getParameter("bookingDate"));new BookingDAO().book(uid,hid,d);s.sendRedirect("halls?booked=1");}catch(Exception e){s.sendRedirect("halls?error=already-booked");}}}
